<script setup>import{ref,onMounted}from'vue';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const items=ref([]);onMounted(async()=>items.value=(await queryEntity('materials')).data.items)</script><template><div class="admin-page"><PageHeader title="库存物料" description="维护板材、五金与台面材料，低于安全库存时自动预警"><el-button type="primary">新增物料</el-button></PageHeader><div class="inventory-strip"><div><b>{{items.length}}</b><span>物料档案</span></div><div><b>{{items.filter(x=>x.warning).length}}</b><span>低库存预警</span></div><div><b>{{new Set(items.map(x=>x.supplier)).size}}</b><span>关联供应商</span></div></div><div class="work-surface"><div class="filter-bar"><el-input placeholder="物料名称 / 型号" style="width:230px"/><el-select placeholder="全部分类" style="width:140px"><el-option label="板材" value="板材"/><el-option label="五金" value="五金"/></el-select><el-checkbox>仅看低库存</el-checkbox><el-button type="primary" plain>查询</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="物料编码" width="130"/><el-table-column prop="name" label="物料名称" min-width="200"/><el-table-column prop="model" label="型号" width="100"/><el-table-column prop="category" label="分类" width="90"/><el-table-column label="当前库存" width="110"><template #default="{row}"><b :style="{color:row.warning?'var(--danger)':'inherit'}">{{row.stock}} {{row.unit}}</b></template></el-table-column><el-table-column prop="safeStock" label="安全库存" width="100"/><el-table-column prop="supplier" label="供应商" min-width="150"/><el-table-column label="预警" width="100"><template #default="{row}"><span :class="['status',row.warning?'warning':'success']">{{row.warning?'需补货':'正常'}}</span></template></el-table-column><el-table-column label="操作" width="110"><template #default><el-button link type="primary">库存调整</el-button></template></el-table-column></el-table></div></div></div></template><style scoped>.inventory-strip{display:flex;background:#fff;border:1px solid var(--border);margin-bottom:16px}.inventory-strip>div{min-width:180px;padding:14px 20px;border-right:1px solid var(--border)}.inventory-strip b,.inventory-strip span{display:block}.inventory-strip b{font-size:22px;font-family:var(--display)}.inventory-strip span{font-size:12px;color:var(--muted)}@media(max-width:600px){.inventory-strip{overflow:auto}.inventory-strip>div{min-width:145px}}</style>
